import { contentsPath, type GitHubApp, type RepositoryRef, repoPath } from './client';
import { utf8ToBase64 } from './encoding';

export interface ProposedChange {
  repository: RepositoryRef;
  /** Branch the pull request targets (the repository's default branch). */
  base: string;
  /** New branch, always generated by the server (`contribute/<id>`). */
  branch: string;
  path: string;
  content: string;
  /** Blob sha of the file being replaced; omit to create a new file. */
  sha?: string;
  message: string;
  title: string;
  body: string;
  /** Labels added after the pull request opens (one more call). */
  labels?: string[];
}

export interface OpenedPullRequest {
  number: number;
  url: string;
  /** False when the labels could not be added; the pull request itself is open. */
  labelled?: boolean;
}

/**
 * Commit one file on a new branch and open a pull request — never a commit to the default branch (ADR 0003).
 * Budget with warm caches: 4 GitHub calls (base ref, new ref, contents, pull request), 5 with labels; +2 on a cold
 * cache (installation id, installation token). Asserted in tests.
 */
export async function proposeChange(github: GitHubApp, change: ProposedChange): Promise<OpenedPullRequest> {
  const repo = repoPath(change.repository);
  // Validate the file path before any call, so an unsafe path never leaves a branch behind.
  const filePath = contentsPath(change.path);
  const base = await github.request<{ object: { sha: string } }>(
    change.repository, 'GET', `${repo}/git/ref/heads/${encodeURIComponent(change.base)}`, 'get base branch',
  );
  await github.request(change.repository, 'POST', `${repo}/git/refs`, 'create branch', {
    ref: `refs/heads/${change.branch}`,
    sha: base.object.sha,
  });
  let pull: { number: number; html_url: string };
  try {
    await github.request(change.repository, 'PUT', `${repo}/contents/${filePath}`, 'write file', {
      message: change.message,
      content: utf8ToBase64(change.content),
      branch: change.branch,
      ...(change.sha ? { sha: change.sha } : {}),
    });
    pull = await github.request<{ number: number; html_url: string }>(change.repository, 'POST', `${repo}/pulls`, 'open pull request', {
      title: change.title,
      body: change.body,
      head: change.branch,
      base: change.base,
      maintainer_can_modify: true,
    });
  } catch (error) {
    // No pull request will point at this branch: remove it (best effort) so no orphan stays behind.
    await github
      .request(change.repository, 'DELETE', `${repo}/git/refs/heads/${change.branch.split('/').map(encodeURIComponent).join('/')}`, 'delete branch')
      .catch(() => undefined);
    throw error;
  }
  // The pull request exists from here on: a labelling failure must not turn it into an error (and a retried duplicate).
  let labelled = true;
  if (change.labels?.length) {
    labelled = await github
      .request(change.repository, 'POST', `${repo}/issues/${pull.number}/labels`, 'add labels', { labels: change.labels })
      .then(() => true, () => false);
  }
  return { number: pull.number, url: pull.html_url, labelled };
}
